    "sanskritGujarati": "સત્સઙ્ગઃ સ્થાપિતસ્તસ્માદ્ દિવ્યોઽયં પરબ્રહ્મણા।\nસ્વામિનારાયણેનેહ સાક્ષાદેવાઽવતીર્ય ચ॥ ૬॥",
