    "sanskritDevanagari": "सत्सङ्गस्याऽस्य विज्ञानं मुमुक्षूणां भवेदिति।\nशास्त्रं सत्सङ्गदीक्षेति शुभाऽऽशयाद् विरच्यते॥ ७॥",
    "sanskritGujarati": "સત્સઙ્ગસ્યાઽસ્ય વિજ્ઞાનં મુમુક્ષૂણાં ભવેદિતિ।\nશાસ્ત્રં સત્સઙ્ગદીક્ષેતિ શુભાઽઽશયાદ્ વિરચ્યતે॥ ૭॥",
    "sanskritIast": "Satsangasyā’sya vignānam mumukṣhūṇām bhaved iti;\nShāstram Satsanga-Dīkṣheti shubhā’shayād virachyate. 7",
    "meaningGu": "આ સત્સંગનું જ્ઞાન મુમુક્ષુઓને થાય એવા શુભ આશયથી ‘સત્સંગદીક્ષા’ એ નામનું શાસ્ત્ર રચવામાં આવે છે. (૭)",
    "meaningHi": "इस सत्संग का ज्ञान मुमुक्षुओं को प्राप्त हो, इस शुभ आशय से ‘सत्संगदीक्षा’ नामक शास्त्र की रचना की जा रही है। (७)",
    "meaningEn": "The shastra titled ‘Satsang Diksha’ has been composed with the pure intent that mumukshus acquire the knowledge of this Satsang. (7)",
    "meaningMr": "या सत्संगाचे ज्ञान मुमुक्षूंना व्हावे, अशा शुभ हेतूने ‘सत्संगदीक्षा’ या नावाचा ग्रंथ रचण्यात आला आहे. (7)",
