        "topic": "દ્રઢ આશ્રય અને અનન્ય શરણાગતિ",
        "textGu": "જેને ભગવાનનો દ્રઢ આશ્રય હોય તેને કોઈ કાળે માયાનો ભય રહેતો નથી. અને ગમે તેવો વિકટ કાળ આવે તો પણ ભગવાનની શરણાગતિ મુકે નહીં, તેને ભગવાન સર્વ સંકટમાંથી ઉગારે છે.",
