        "textEn": "One who has firm refuge (aashray) in Bhagwan is never troubled by the fears of Maya; Bhagwan protects them through all adversities.",
        "quoteGu": "દ્રઢ આશ્રય વિના તો કોઈ વાતની સિદ્ધિ થતી નથી.",
