        "textGu": "ભગવાનના ભક્તને તો કંઠી ને તિલક-ચાંદલો એ સત્સંગનું બાહ્ય ચિહ્ન છે અને અંતરમાં દ્રઢ નિષ્ઠા એ આંતરિક અંગ છે. એ બેય રાખે તે સાચો હરિભક્ત.",
