    "sanskritDevanagari": "नोत्तमो निर्विकल्पश्च निश्चयः परमात्मनः।\nन स्वात्मब्रह्मभावोऽपि ब्रह्माऽक्षरं गुरुं विना॥ २३॥",
    "sanskritGujarati": "નોત્તમો નિર્વિકલ્પશ્ચ નિશ્ચયઃ પરમાત્મનઃ।\nન સ્વાત્મબ્રહ્મભાવોઽપિ બ્રહ્માઽક્ષરં ગુરું વિના॥ ૨૩॥",
