    "titleHi": "श्लोक 36",
    "titleEn": "Shloka 36",
    "sanskritDevanagari": "यागादिके च कर्तव्ये सिद्धान्तं सांप्रदायिकम्।\nअनुसृत्य हि कर्तव्यं हिंसारहितमेव तत्॥ ३६॥",
    "sanskritGujarati": "યાગાદિકે ચ કર્તવ્યે સિદ્ધાન્તં સાંપ્રદાયિકમ્।\nઅનુસૃત્ય હિ કર્તવ્યં હિંસારહિતમેવ તત્॥ ૩૬॥",
    "sanskritIast": "Yāgādike cha kartavye siddhāntam sāmpradāyikam;\nAnusṛutya hi kartavyam hinsā-rahitam eva tat. 36",
    "meaningGu": "યાગાદિ કરવાના થાય ત્યારે સંપ્રદાયના સિદ્ધાંતને અનુસરીને હિંસારહિત જ કરવા. (૩૬)",
    "meaningHi": "यज्ञ आदि करना हो, तब संप्रदाय के सिद्धांत के अनुसार हिंसारहित ही करें। (३६)",
    "meaningEn": "When yagnas are held, they should only be conducted without harming any beings and according to the Sampraday’s principles. (36)",
    "meaningMr": "यज्ञयाग करावयाचे असल्यास, संप्रदायाच्या सिद्धांतानुसार हिंसारहितच करावेत. (36)",
