        "textGu": "રોજ સવારે પૂજા કર્યા વિના અન્ન-જળ ન લેવું. પૂજામાં એકાગ્રતા રાખવી અને માળા ફેરવતી વખતે મૂર્તિનું ધ્યાન ધરવું.",
