    "titleEn": "Shloka 38",
    "sanskritDevanagari": "कस्याऽपि ताडनं नैव करणीयं कदाचन।\nअपशब्दाऽपमानादि-सूक्ष्महिंसाऽपि नैव च॥ ३८॥",
    "sanskritGujarati": "કસ્યાઽપિ તાડનં નૈવ કરણીયં કદાચન।\nઅપશબ્દાઽપમાનાદિ-સૂક્ષ્મહિંસાઽપિ નૈવ ચ॥ ૩૮॥",
    "sanskritIast": "Kasyā’pi tāḍanam naiva karaṇīyam kadāchana;\nApa-shabdā’pamānādi-sūkṣhma-hinsā’pi naiva cha. 38",
    "meaningGu": "કોઈનું તાડન ક્યારેય ન કરવું. અપશબ્દો કહેવા, અપમાન કરવું ઇત્યાદિ કોઈપણ પ્રકારે સૂક્ષ્મ હિંસા પણ ન કરવી. (૩૮)",
    "meaningHi": "कदापि किसी का ताड़न न करें। अपशब्द कहना, अपमानित करना इत्यादि किसी भी प्रकार की सूक्ष्म हिंसा भी न करें। (३८)",
    "meaningEn": "One should never strike another person. One should not swear, insult or commit other forms of subtle harm or injury. (38)",
    "meaningMr": "कधीही कोणाला ताडन करू नये, अपशब्द बोलणे, अपमान करणे इत्यादी कोठल्याही प्रकारे सूक्ष्म (किंचितही) हिंसा सुद्धा करू नये. (38)",
