    "titleEn": "Shloka 46",
    "sanskritDevanagari": "नूनं नङ्क्ष्यन्ति मे विघ्नाः पापदोषाश्च दुर्गुणाः।\nनूनं प्राप्स्याम्यहं शान्तिमानन्दं परमं सुखम्॥ ४६॥",
    "sanskritGujarati": "નૂનં નઙ્ક્ષ્યન્તિ મે વિઘ્નાઃ પાપદોષાશ્ચ દુર્ગુણાઃ।\nનૂનં પ્રાપ્સ્યામ્યહં શાન્તિમાનન્દં પરમં સુખમ્॥ ૪૬॥",
    "sanskritIast": "Nūnam nankṣhyanti me vighnāh pāpa-doṣhāsh-cha dur-guṇāhā;\nNūnam prāpsyāmyaham shāntim ānandam paramam sukham. 46",
    "meaningGu": "મારાં વિઘ્નો, પાપ, દોષ તથા દુર્ગુણો અવશ્ય નાશ પામશે. હું અવશ્ય શાંતિ, પરમ આનંદ અને સુખ પામીશ. (૪૬)",
    "meaningHi": "मेरे विघ्न, पाप, दोष तथा दुर्गुण अवश्य नष्ट होंगे। मैं शांति, सुख और परम आनंद को अवश्य प्राप्त करूँगा। (४६)",
    "meaningEn": "My hindrances, sins, flaws and bad qualities will certainly be destroyed. I will surely attain peace, supreme bliss and happiness. (46)",
    "meaningMr": "माझी विघ्ने, पाप, दोष तसेच दुर्गुण अवश्य नाश पावतील. मी अवश्य शांती, परम आनंद आणि सुख प्राप्त करीन. (46)",
