    "titleGu": "શ્લોક 48",
    "titleHi": "श्लोक 48",
    "titleEn": "Shloka 48",
    "sanskritDevanagari": "विचार्यैवं बलं रक्षेद् नाऽऽश्रितो निर्बलो भवेत्।\nआनन्दितो भवेन्नित्यं भगवद्‌बलवैभवात्॥ ४८॥",
    "sanskritGujarati": "વિચાર્યૈવં બલં રક્ષેદ્ નાઽઽશ્રિતો નિર્બલો ભવેત્।\nઆનન્દિતો ભવેન્નિત્યં ભગવદ્‌બલવૈભવાત્॥ ૪૮॥",
    "sanskritIast": "Vichāryaivam balam rakṣhed nā’shrito nirbalo bhavet;\nĀnandito bhaven-nityam Bhagavad bala vaibhavāt. 48",
    "meaningGu": "આ રીતે વિચારનું બળ રાખી આશ્રિત ભક્ત ક્યારેય હિંમત ન હારે અને ભગવાનના બળે આનંદમાં રહે. (૪૮)",
    "meaningHi": "इस तरह विचार का बल रखकर आश्रित भक्त कदापि हिम्मत न हारे और भगवान के बल से सदा आनंद में रहे। (४८)",
    "meaningEn": "With the strength of such thoughts, a devotee who has taken refuge never loses courage and remains joyous due to the strength of Bhagwan. (48)",
    "meaningMr": "अशा रीतीने विचारांचे बळ राखून, आश्रित भक्ताने कधीही हिंमत न हारता भगवंतांच्या बळाने आनंदात रहावे. (48)",
