    "sanskritGujarati": "ષ્ઠીવનં મલમૂત્રાદિવિસર્જનં સ્થલેષુ ચ।\nશાસ્ત્રલોકનિષિદ્ધેષુ ન કર્તવ્યં કદાચન॥ ૪૯॥",
